"use client";

import { useState, useEffect, useCallback } from 'react';

// Función de utilidad para manejar localStorage de forma segura
const getFromLocalStorage = (key) => {
  try {
    if (typeof window === 'undefined') return null;
    return localStorage.getItem(key);
  } catch (error) {
    console.error(`Error getting ${key} from localStorage:`, error);
    return null;
  }
};

// Función para parsear JSON con manejo de errores
const safeJsonParse = (jsonString, fallback = null) => {
  try {
    return jsonString ? JSON.parse(jsonString) : fallback;
  } catch (error) {
    console.error('Error parsing JSON:', error);
    return fallback;
  }
};

// Función para crear sesión desde localStorage - simplificada
const createSessionFromStorage = () => {
  // Priorizar bisonte_mobile_session como fuente principal
  const mobileSession = getFromLocalStorage('bisonte_mobile_session');
  if (mobileSession) {
    const sessionData = safeJsonParse(mobileSession);
    if (sessionData && sessionData.user) {
      return {
        user: sessionData.user,
        token: sessionData.token || sessionData.access_token,
        refreshToken: sessionData.refreshToken || sessionData.refresh_token,
        expires: sessionData.expires || sessionData.expires_at,
        created: sessionData.created || new Date().toISOString()
      };
    }
  }

  // Fallback: construir desde datos básicos user + authToken
  const user = getFromLocalStorage('user');
  const authToken = getFromLocalStorage('authToken');
  
  if (user && authToken) {
    const userData = safeJsonParse(user);
    if (userData && userData.email) {
      return {
        user: userData,
        token: authToken,
        refreshToken: getFromLocalStorage('refreshToken'),
        expires: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
        created: new Date().toISOString()
      };
    }
  }

  console.log('No valid session found in localStorage');
  return null;
};

// Función para guardar sesión
const saveSessionToStorage = (sessionData) => {
  try {
    if (typeof window === 'undefined') return;
    
    // Guardar en bisonte_mobile_session como fuente principal
    localStorage.setItem('bisonte_mobile_session', JSON.stringify(sessionData));
    
    // Mantener compatibilidad con sistema existente
    if (sessionData.user) {
      localStorage.setItem('user', JSON.stringify(sessionData.user));
    }
    if (sessionData.token) {
      localStorage.setItem('authToken', sessionData.token);
    }
    if (sessionData.refreshToken) {
      localStorage.setItem('refreshToken', sessionData.refreshToken);
    }
    
    console.log('Session saved successfully');
  } catch (error) {
    console.error('Error saving session to localStorage:', error);
  }
};

// Función para limpiar localStorage
const clearSession = () => {
  try {
    if (typeof window === 'undefined') return;
    
    const keysToRemove = [
      'bisonte_mobile_session',
      'user',
      'authToken',
      'refreshToken',
      'google_auth_data',
      'session_data'
    ];
    
    keysToRemove.forEach(key => {
      localStorage.removeItem(key);
    });
    
    console.log('Session cleared successfully');
  } catch (error) {
    console.error('Error clearing session:', error);
  }
};

export const useMobileSession = () => {
  const [session, setSession] = useState(null);
  const [isLoading, setIsLoading] = useState(true);

  // Función para cargar la sesión
  const loadSession = useCallback(() => {
    setIsLoading(true);
    const sessionData = createSessionFromStorage();
    setSession(sessionData);
    setIsLoading(false);
    return sessionData;
  }, []);

  // Función para actualizar la sesión
  const updateSession = useCallback((newSessionData) => {
    const sessionToSave = {
      ...newSessionData,
      created: newSessionData.created || new Date().toISOString()
    };
    
    saveSessionToStorage(sessionToSave);
    setSession(sessionToSave);
    return sessionToSave;
  }, []);

  // Función para logout
  const logout = useCallback(() => {
    clearSession();
    setSession(null);
  }, []);

  // Cargar sesión al inicializar
  useEffect(() => {
    loadSession();
  }, [loadSession]);

  // Verificar si hay sesión válida
  const isAuthenticated = !!(session && session.user && session.token);

  // Verificar si la sesión ha expirado
  const isExpired = session?.expires ? new Date(session.expires) < new Date() : false;

  return {
    session,
    isAuthenticated: isAuthenticated && !isExpired,
    isLoading,
    updateSession,
    logout,
    loadSession,
    isExpired
  };
};

export default useMobileSession;
